#include "freertos/FreeRTOS.h"
#include "freertos/task.h"
#include "driver/gpio.h"

#define LED_GPIO GPIO_NUM_2

void app_main(void) {
    gpio_reset_pin(LED_GPIO);
    gpio_set_direction(LED_GPIO, GPIO_MODE_OUTPUT);
    uint8_t level = 0;
    while (1) {
        gpio_set_level(LED_GPIO, level);
        level = !level;
        vTaskDelay(pdMS_TO_TICKS(500));   // låter andra tasks köra under tiden
    }
}

class Led {
public:
    explicit Led(gpio_num_t pin) : pin_(pin) {
        gpio_reset_pin(pin_);
        gpio_set_direction(pin_, GPIO_MODE_OUTPUT);
    }
    void on()  { set(true); }
    void off() { set(false); }
    void toggle() { set(!on_); }
private:
    void set(bool on) { on_ = on; gpio_set_level(pin_, on ? 1 : 0); }
    gpio_num_t pin_;
    bool on_ = false;
};
